      "bioShortLabel": "50 Words",
      "bioShort": "Michael Kofman is CEO of Digital Invest Inc. and a board member, advisor, and founder of companies in technology and digital health across the U.S. and Europe.",
      "bioMediumLabel": "150 Words",
      "bioMedium": "Michael Kofman is CEO of Digital Invest Inc. and serves on its board. An entrepreneur, board member, and advisor, he has founded companies in the U.S. and Europe across data infrastructure, digital health, and robotics. His work spans technology strategy, security, research, and investment.",
      "bioLongLabel": "500 Words",
      "bioLong": "Michael Kofman is CEO of Digital Invest Inc. and serves on its board. He founded 9 Net Avenue Inc., acquired by Concentric Networks in 2000, and leads Digital Invest in bio-mathematical medicine and genomic intelligence. He founded AGRON Inc. in 2026 for autonomous aerial-ground operations and geospatial systems. Author of technical papers on satellite and optical systems; patent in digital satellite HDTV acquired by Sony. Education: Doctor of Technical Sciences, Ph.D. in Information Technology.",
