    "articles": {
      "backLink": "← Volver a Insights",
      "article1date": "Perspectiva ejecutiva",
      "article1title": "De la ingeniería a la infraestructura global de datos",
      "article1p1": "Mi carrera comenzó en la planta de construcción naval de Nikolaev, en Ucrania, desarrollando sistemas transceptores satelitales para transmitir información clasificada a buques militares. Fui reconocido como ingeniero electrónico del más alto nivel: la 6.ª categoría en una planta de 93.000 empleados.",
      "article1p2": "Entre 1989 y 1994 fundé y dirigí Astra Corp, uno de los mayores fabricantes europeos de sistemas satelitales transceptores digitales. De 1994 a 1996, como CEO de Elitan United Inc., ayudé a escalar la empresa de nueve a más de 4.000 empleados en todo el mundo.",
      "article1p3": "In 1996, I founded 9 Net Avenue Inc., a hosting and internet infrastructure company. In 2000 it was acquired by Concentric Networks (NASDAQ: CNTX) and subsequently became part of XO Communications (NASDAQ: XOXO).",
      "article1p4": "De 2001 a 2019 dirigí la estrategia tecnológica para programas gubernamentales, de defensa y de empresas estatales, liderando iniciativas de gran escala en big data, infraestructura segura y centros de datos de alto rendimiento en Estados Unidos y Europa.",
      "article2date": "Salud digital",
      "article2title": "Medicina de precisión y convergencia entre ciencia y tecnología",
      "article2p1": "Creo firmemente en el potencial de combinar las ciencias de la vida con los últimos avances tecnológicos. En Biotechnology Group Inc. (2008-2014), nos enfocamos en pruebas y análisis de ADN, automatización de procesos para crear perfiles genéticos e investigación genética humana integral.",
      "article2p2": "Bajo mi liderazgo, se iniciaron proyectos exitosos de pruebas genéticas en Ucrania, Rusia y los países bálticos. En colaboración con Harvard Medical School y Stanford Biomath, desempeñé un papel clave en el desarrollo de reportes genéticos fáciles de comprender para médicos y pacientes.",
      "article2p3": "Con Digital Invest Inc., fundada en 2021, trabajamos en medicina biomatemática — ciencia, tecnologías de ADN, IA y ML aplicadas a inteligencia clínica. Healthcare Tech Outlook (2023).",
      "article2p4": "Digital Invest impulsa la medicina biomatemática con proyectos como Human Digital Model y BioMath Life. En 2026, Michael Kofman fundó AGRON Inc. para liderar la Aerial-Ground Robotics Operations Network — desarrollo de capacidades UAV, sistemas geoespaciales e inteligencia marítima en agron1.com."
    },
