    "articles": {
      "backLink": "← Retour vers Insights",
      "article1date": "Perspective dirigeante",
      "article1title": "De l'ingénierie à l'infrastructure mondiale de données",
      "article1p1": "Ma carrière a commencé à l'usine navale de Nikolaev, en Ukraine, où je développais des systèmes transpondeurs satellitaires pour transmettre des informations classifiées aux navires militaires. J'ai été reconnu comme ingénieur en électronique de plus haut niveau, 6e catégorie, dans une usine de 93 000 employés.",
      "article1p2": "De 1989 à 1994, j'ai fondé et dirigé Astra Corp, l'un des plus grands fabricants européens de systèmes satellitaires transpondeurs numériques. De 1994 à 1996, en tant que CEO d'Elitan United Inc., j'ai contribué à faire passer l'entreprise de neuf à plus de 4 000 employés dans le monde.",
      "article1p3": "In 1996, I founded 9 Net Avenue Inc., a hosting and internet infrastructure company. In 2000 it was acquired by Concentric Networks (NASDAQ: CNTX) and subsequently became part of XO Communications (NASDAQ: XOXO).",
      "article1p4": "De 2001 à 2019, j'ai dirigé la stratégie technologique pour des programmes gouvernementaux, de défense et d'entreprises publiques, en menant de grandes initiatives dans le big data, l'infrastructure sécurisée et les data centers à haut débit aux États-Unis et en Europe.",
      "article2date": "Santé numérique",
      "article2title": "Médecine de précision et convergence de la science et de la technologie",
      "article2p1": "Je crois fermement au potentiel de la combinaison des sciences de la vie avec les dernières avancées technologiques. Chez Biotechnology Group Inc. (2008-2014), nous nous sommes concentrés sur les tests et analyses ADN, l'automatisation des processus de création de profils génétiques et la recherche génétique humaine complète.",
      "article2p2": "Sous ma direction, des projets réussis de tests génétiques ont été lancés en Ukraine, en Russie et dans les pays baltes. En collaboration avec Harvard Medical School et Stanford Biomath, j'ai joué un rôle clé dans le développement de rapports génétiques faciles à comprendre pour les médecins comme pour les patients.",
      "article2p3": "Avec Digital Invest Inc., fondée en 2021, nous travaillons en médecine biomathématique — science, technologies ADN, IA et ML appliquées à l'intelligence clinique. Healthcare Tech Outlook (2023).",
      "article2p4": "Digital Invest fait progresser la médecine bio-mathématique via des projets comme Human Digital Model et BioMath Life. En 2026, Michael Kofman a fondé AGRON Inc. pour diriger l'Aerial-Ground Robotics Operations Network — capacités UAV, systèmes géospatiaux et renseignement maritime sur agron1.com."
    },
